const $=s=>document.querySelector(s),form=$('[data-suggestion-form]'),status=$('[data-suggestion-status]');
async function api(path='',method='GET',body){const response=await fetch('/api/suggestions'+path,{method,cache:'no-store',...(body?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'No se ha podido completar la operación.'),{status:response.status});return data;}
form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;status.textContent='Enviando tu idea…';const values=Object.fromEntries(new FormData(form));try{await api('','POST',{...values,consent:form.elements.consent.checked});form.reset();status.textContent='¡Gracias! Tu idea ha llegado al buzón privado de los administradores.';if(!$('[data-suggestion-management]').hidden)await load();}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
const element=(tag,text)=>{const node=document.createElement(tag);node.textContent=text;return node;};let suggestions=[];
const labels={new:'Nueva',read:'Leída',archived:'Archivada'};
function render(){const list=$('[data-suggestion-list]'),filter=$('[data-suggestion-filter]').value,items=suggestions.filter(item=>!filter||item.status===filter);list.replaceChildren();$('[data-suggestion-count]').textContent=`${suggestions.filter(item=>item.status==='new').length} nuevas · ${suggestions.length} propuestas en las últimas 200 recibidas.`;if(!items.length){list.append(element('p','No hay sugerencias en este apartado.'));return;}
 for(const item of items){const card=element('article','');card.className='suggestion-card';const metadata=element('p',labels[item.status]+' · '+item.category+' · '+new Intl.DateTimeFormat('es-ES',{dateStyle:'medium'}).format(new Date(item.created_at*1000)));metadata.className='suggestion-meta';card.append(metadata,element('h3',item.title),element('p',item.idea),element('small',item.alias?'Enviada por '+item.alias:'Sin nombre o alias'));const actions=element('div','');actions.className='suggestion-actions';for(const [next,label]of [['read','Marcar como leída'],['archived','Archivar'],['new','Marcar como nueva'],['delete','Eliminar']]){if(next===item.status)continue;const button=element('button',label);button.type='button';button.addEventListener('click',async()=>{if(next==='delete'&&!confirm('¿Eliminar definitivamente esta sugerencia?'))return;button.disabled=true;try{await api('/'+item.id,next==='delete'?'DELETE':'POST',next==='delete'?undefined:{status:next});await load();}catch(error){$('[data-suggestion-review-status]').textContent=error.message;button.disabled=false;}});actions.append(button);}card.append(actions);list.append(card);}
}
async function load(){try{suggestions=await api();$('[data-suggestion-management]').hidden=false;$('[data-suggestion-login]').hidden=true;render();$('[data-suggestion-review-status]').textContent='Buzón privado: solo los administradores pueden leer y gestionar las propuestas.';}catch(error){if(error.status===401){suggestions=[];$('[data-suggestion-list]').replaceChildren();$('[data-suggestion-management]').hidden=true;$('[data-suggestion-login]').hidden=false;}else $('[data-suggestion-review-status]').textContent=error.message;}}
$('[data-suggestion-filter]').addEventListener('change',render);$('[data-suggestion-refresh]').addEventListener('click',load);window.addEventListener('club-session-change',load);void load();
